        // llama.cpp's own storage is `int32_t`; see `NgramMod::add`'s doc.
        out[n_match + step] = token as u32;
    }

    for index in 0..drafted_len {
        out[index] = out[n_match + index];
    }
    out.truncate(drafted_len);

    mod_.n_draft_last = out.len();
